mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM wallet
    WHERE user_id = #{userId}
      AND status = 'ACTIVE'
)

SELECT EXISTS (
    SELECT 1
    FROM wallet_account wa
             INNER JOIN accounts a
                        ON a.id = wa.account_id
                           AND a.is_deleted = 0
    WHERE wa.wallet_id = #{walletId}
      AND wa.account_id = #{accountId}
      AND wa.status = 'LINKED'
)

SELECT EXISTS (
    SELECT 1
    FROM accounts
    WHERE id = #{accountId}
      AND user_id = #{userId}
      AND is_deleted = 0
)

SELECT EXISTS (
    SELECT 1
    FROM wallet_ledger
    WHERE idempotency_key = #{idempotencyKey}
)

SELECT EXISTS (
    SELECT 1
    FROM travel_card_ledger
    WHERE idempotency_key = #{idempotencyKey}
)

SELECT EXISTS (
    SELECT 1
    FROM travel_card_currencies
    WHERE card_id = #{travelCardId}
      AND currency_code = #{currencyCode}
      AND is_deleted = 0
)

mapper.update:
UPDATE wallet_account
SET is_primary = TRUE
WHERE wallet_id = #{walletId}
  AND account_id = #{accountId}
  AND status = 'LINKED'

UPDATE accounts
SET balance = COALESCE(balance, 0) - #{amount},
    withdrawable_amount = COALESCE(withdrawable_amount, 0) - #{amount},
    updated_at = NOW()
WHERE id = #{accountId}
  AND user_id = #{userId}
  AND is_deleted = 0
  AND is_active = TRUE
  AND COALESCE(withdrawable_amount, balance, 0) >= #{amount}

mapper.select:
SELECT balance
FROM accounts
WHERE id = #{accountId}
  AND user_id = #{userId}
  AND is_deleted = 0
  AND is_active = TRUE

mapper.update:
UPDATE wallet
SET balance_amount = #{balanceAmount},
    version = version + 1
WHERE id = #{walletId}
  AND version = #{version}
  AND status = 'ACTIVE'

UPDATE travel_card_balance
SET balance_amount = #{balanceAmount},
    krw_estimated_amount = #{krwEstimatedAmount}
WHERE id = #{balanceId}

mapper.select:
SELECT COALESCE(SUM(
    CASE WHEN wl.direction = 'IN' THEN wl.amount
         ELSE -wl.amount END
), 0)
FROM wallet_ledger wl
WHERE wl.wallet_id = #{walletId}
  AND DATE(wl.created_at) <= #{asOfDate}
